-- GenDB engine variant Q11-commuted_comparisons: template q11.sql, kind commuted_comparisons (generated by generate.py; frozen)
SELECT
  ps_partkey,
  SUM(ps_supplycost * ps_availqty) AS value
FROM partsupp, supplier, nation
WHERE
  s_suppkey = ps_suppkey AND n_nationkey = s_nationkey AND $1 = n_name
GROUP BY
  ps_partkey
HAVING
  (
    SELECT
      SUM(ps_supplycost * ps_availqty) * $2
    FROM partsupp, supplier, nation
    WHERE
      s_suppkey = ps_suppkey AND n_nationkey = s_nationkey AND $1 = n_name
  ) < SUM(ps_supplycost * ps_availqty)
ORDER BY
  value DESC
